/**
 * AURA ALPHA — usePullToRefresh
 * Provides pull-to-refresh gesture support for mobile native pages.
 * Returns a ref to attach to the scrollable container and a refreshing state.
 *
 * Usage:
 *   const { containerRef, isRefreshing } = usePullToRefresh(onRefresh);
 */
import { useState, useRef, useEffect, useCallback } from 'react';

export function usePullToRefresh(onRefresh, { threshold = 80, disabled = false } = {}) {
  const containerRef = useRef(null);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const startY = useRef(0);
  const pulling = useRef(false);

  const handleRefresh = useCallback(async () => {
    if (isRefreshing || disabled) return;
    setIsRefreshing(true);
    try {
      await onRefresh?.();
    } finally {
      setIsRefreshing(false);
    }
  }, [onRefresh, isRefreshing, disabled]);

  useEffect(() => {
    const el = containerRef.current || window;

    function onTouchStart(e) {
      if (disabled) return;
      const scrollTop = el === window ? window.scrollY : el.scrollTop;
      if (scrollTop <= 0) {
        startY.current = e.touches[0].clientY;
        pulling.current = true;
      }
    }

    function onTouchEnd(e) {
      if (!pulling.current) return;
      pulling.current = false;
      const endY = e.changedTouches[0].clientY;
      const delta = endY - startY.current;
      if (delta > threshold) {
        handleRefresh();
      }
    }

    el.addEventListener('touchstart', onTouchStart, { passive: true });
    el.addEventListener('touchend', onTouchEnd, { passive: true });
    return () => {
      el.removeEventListener('touchstart', onTouchStart);
      el.removeEventListener('touchend', onTouchEnd);
    };
  }, [handleRefresh, threshold, disabled]);

  return { containerRef, isRefreshing };
}

export default usePullToRefresh;
